package com.projetok.studio;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.*;
import java.nio.file.*;
import java.util.*;
import javax.imageio.ImageIO;
import com.projetok.prototype.*;
import com.projetok.prototype.rpg.*;

/** Homologacao automatizada de janelas reais; usa copia descartavel dos PNGs, nunca saves pessoais. */
public final class WorldStudioUiProbe {
    static WorldStudio editor;static JFrame game;static DebugPanel panel;static RpgRuntime runtime;static Path out,project;static int phase,watch;static long tick;static float before,blocked;
    static <T> T find(Container c,Class<T> type){for(Component x:c.getComponents()){if(type.isInstance(x))return type.cast(x);if(x instanceof Container child){T p=find(child,type);if(p!=null)return p;}}return null;}
    static void capture(JFrame f,String name)throws Exception{var image=new BufferedImage(f.getWidth(),f.getHeight(),BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();f.printAll(g);g.dispose();ImageIO.write(image,"png",out.resolve(name+".png").toFile());}
    static AssetCatalog.Asset asset(String suffix){return editor.catalog.assets().stream().filter(a->a.path().replace('\\','/').endsWith(suffix)).findFirst().orElseThrow();}
    static WorldDocument.Element object(String id,AssetCatalog.Asset a,int x,int y,String layer){return new WorldDocument.Element(id,WorldDocument.Kind.OBJECT,a.id(),a.sha(),new WorldDocument.Crop(0,0,a.width(),a.height()),x,y,a.width(),a.height(),layer,true,false,"","FRONT",Map.of());}
    /** Argumentos: pasta nova de evidencias e projeto de origem somente leitura. */
    public static void main(String[] args)throws Exception{out=Path.of(args[0]).toAbsolutePath();Files.createDirectory(out);project=Files.createDirectory(out.resolve("project"));var catalog=AssetCatalog.scan(Path.of(args[1]),null);for(var a:catalog.assets()){Path target=project.resolve(a.path());Files.createDirectories(target.getParent());Files.copy(a.file(),target);}UUID.randomUUID();Path temp=Files.createTempFile(out,"warm-",".tmp");Files.delete(temp);SwingUtilities.invokeAndWait(()->{editor=new WorldStudio(project);editor.setVisible(true);editor.rescan();var timer=new javax.swing.Timer(70,e->{try{step();}catch(Exception error){error.printStackTrace();System.exit(2);}});timer.start();});}
    @SuppressWarnings("unchecked") static void step()throws Exception{if(++watch>1600)throw new IllegalStateException("UI timeout phase "+phase);
        if(phase==0&&editor.refresh.isEnabled()&&editor.catalog.assets().size()==248){
            var grass=asset("karakura-v3-separated/sprite-001.png");editor.brush=grass;editor.brushCrop=new WorldDocument.Crop(0,0,grass.width(),grass.height());for(Component c:editor.toolbar.getComponents())if(c instanceof JComboBox<?> box){if(box.getItemCount()>0&&"Selecionar".equals(box.getItemAt(0)))((JComboBox<String>)box).setSelectedItem("Retangulo");if(box.getItemCount()>0&&"Objeto real".equals(box.getItemAt(0)))box.setSelectedIndex(1);}
            var a=editor.canvas.viewport.screen(0,0);var b=editor.canvas.viewport.screen(959,639);editor.canvas.dispatchEvent(new MouseEvent(editor.canvas,MouseEvent.MOUSE_PRESSED,System.currentTimeMillis(),0,(int)a.x,(int)a.y,1,false,MouseEvent.BUTTON1));editor.canvas.dispatchEvent(new MouseEvent(editor.canvas,MouseEvent.MOUSE_RELEASED,System.currentTimeMillis(),0,(int)b.x,(int)b.y,1,false,MouseEvent.BUTTON1));if(editor.document.elements().size()!=600)throw new IllegalStateException("Retangulo real nao pintou 600 tiles");editor.getRootPane().getActionMap().get("Desfazer").actionPerformed(new ActionEvent(editor,0,"probe"));if(!editor.document.elements().isEmpty())throw new IllegalStateException("Undo real falhou");editor.getRootPane().getActionMap().get("Refazer").actionPerformed(new ActionEvent(editor,0,"probe"));
            var d=editor.document;var elements=new ArrayList<>(d.elements());elements.addAll(StudioExample.document().elements());elements.add(object("tree",asset("karakura-v3-separated/sprite-048.png"),250,70,"objects"));elements.add(object("house",asset("karakura-v3-separated/sprite-046.png"),500,35,"objects"));d=d.withElements(elements).withHitboxes(java.util.List.of(new WorldDocument.Hitbox("wall",260,280,32,128,true,"collision"),new WorldDocument.Hitbox("house_base",515,260,330,30,true,"collision"))).withPortals(java.util.List.of(new WorldDocument.Portal("portal",750,500,d.id(),140,320,"","FRONT"))).withTriggers(java.util.List.of(new WorldDocument.Trigger("welcome","ENTER","MESSAGE","","Evento de mapa validado no runtime real",0,0,32,32,true)));
            editor.change(d);editor.warmImages();editor.fileTools.file=out.resolve("authored.sgmap");phase=1;editor.fileTools.save(false,()->{try{phase=2;capture(editor,"editor-final");var snapshot=editor.document;new Thread(()->{try{var bundle=StudioExport.write(out.resolve("export"),snapshot.id(),Map.of(snapshot.id(),snapshot),editor.catalog);StudioPlaytest.launch(bundle,project);}catch(Exception error){error.printStackTrace();System.exit(2);}},"probe-export").start();}catch(Exception error){throw new RuntimeException(error);}});
        }else if(phase==2){for(Frame f:Frame.getFrames())if(f instanceof JFrame j&&j.isShowing()&&j.getTitle().contains("PLAYTEST ISOLADO")){game=j;panel=find(game,DebugPanel.class);var hud=find(game,RpgHud.class);var field=RpgHud.class.getDeclaredField("runtime");field.setAccessible(true);runtime=(RpgRuntime)field.get(hud);tick=runtime.snapshot().ticks();before=runtime.snapshot().x();panel.getActionMap().get("Dtrue").actionPerformed(new ActionEvent(panel,0,"probe"));phase=3;return;}}
        else if(phase==3&&runtime.snapshot().ticks()-tick>=30){panel.getActionMap().get("Dfalse").actionPerformed(new ActionEvent(panel,0,"probe"));blocked=runtime.snapshot().x();if(!(blocked>before&&blocked<=242.01))throw new IllegalStateException("Colisao real falhou: "+blocked);panel.getActionMap().get("Ftrue").actionPerformed(new ActionEvent(panel,0,"probe"));tick=runtime.snapshot().ticks();phase=4;}
        else if(phase==4&&runtime.snapshot().ticks()-tick>=5){if(!runtime.snapshot().activeNpc().equals("elder"))throw new IllegalStateException("Interacao NPC real falhou");if(runtime.failure()!=null)throw new IllegalStateException("Runtime falhou",runtime.failure());capture(game,"playtest-final");var mini=new MinimapPanel(()->editor.document,p->{});mini.navigation=NavigationAnalysis.analyze(editor.document);JFrame map=new JFrame("Minimapa real | analise aproximada");map.add(mini);map.pack();map.setVisible(true);capture(map,"minimapa-final");map.dispose();Files.writeString(out.resolve("evidence.json"),"{\"catalogAssets\":"+editor.catalog.assets().size()+",\"paintedTiles\":600,\"realMouseRectangle\":true,\"realUndoRedo\":true,\"savedAndReloaded\":"+DocumentStore.load(out.resolve("authored.sgmap")).equals(editor.document)+",\"initialX\":"+before+",\"blockedX\":"+blocked+",\"npcInteraction\":true,\"runtimeFailure\":false,\"personalSavesUsed\":false,\"humanApproved\":false}");phase=5;game.dispatchEvent(new WindowEvent(game,WindowEvent.WINDOW_CLOSING));editor.dispose();new javax.swing.Timer(600,e->System.exit(0)).start();}
    }
}
